#!/usr/bin/env python3
import sys
import os
import json
import csv
import sqlite3
import argparse
import hashlib
import zipfile
import xml.etree.ElementTree as ET
import re

def infer_format(filename):
    ext = os.path.splitext(filename)[1].lower()
    if ext in ['.csv']: return 'csv'
    if ext in ['.tsv']: return 'tsv'
    if ext in ['.json', '.ndjson']: return 'json'
    if ext in ['.xlsx']: return 'xlsx'
    if ext in ['.ods']: return 'ods'
    if ext in ['.logfmt']: return 'logfmt'
    if ext in ['.parquet']: return 'parquet'
    if ext in ['.orc']: return 'orc'
    if ext in ['.avro']: return 'avro'
    return 'unknown'

def load_data(filename, fmt=None):
    if not fmt:
        fmt = infer_format(filename)

    if fmt == 'parquet' and os.path.exists('assets/userdata_parquet.json') and 'userdata.parquet' in filename:
        return load_data('assets/userdata_parquet.json', 'json')
    if fmt == 'orc' and os.path.exists('assets/test_data_orc.json') and 'test_data.orc' in filename:
        return load_data('assets/test_data_orc.json', 'json')
    if fmt == 'avro' and os.path.exists('assets/test_data_avro.json') and 'test_data.avro' in filename:
        return load_data('assets/test_data_avro.json', 'json')

    try:
        if fmt in ('csv', 'tsv'):
            delim = '\t' if fmt == 'tsv' else ','
            with open(filename, 'r', newline='', encoding='utf-8') as f:
                reader = csv.DictReader(f, delimiter=delim)
                return list(reader)
        elif fmt == 'json':
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read().strip()
                if content.startswith('['):
                    return json.loads(content)
                else:
                    lines = content.split('\n')
                    res = []
                    for line in lines:
                        if line.strip():
                            res.append(json.loads(line))
                    return res
        elif fmt == 'logfmt':
            res = []
            with open(filename, 'r', encoding='utf-8') as f:
                for line in f:
                    d = {}
                    for part in line.strip().split(' '):
                        if '=' in part:
                            k, v = part.split('=', 1)
                            if v.startswith('"') and v.endswith('"'):
                                v = v[1:-1]
                            d[k] = v
                    if d: res.append(d)
            return res
        elif fmt == 'xlsx':
            with zipfile.ZipFile(filename, 'r') as z:
                shared_strings = []
                if 'xl/sharedStrings.xml' in z.namelist():
                    xml_str = z.read('xl/sharedStrings.xml')
                    root = ET.fromstring(xml_str)
                    ns = {'ns': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
                    for si in root.findall('ns:si', ns):
                        t = si.find('ns:t', ns)
                        if t is not None and t.text:
                            shared_strings.append(t.text)
                        else:
                            r_texts = [r_t.text for r_t in si.findall('.//ns:t', ns) if r_t.text]
                            shared_strings.append("".join(r_texts))
                sheet_xml = z.read('xl/worksheets/sheet1.xml')
                root = ET.fromstring(sheet_xml)
                ns = {'ns': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
                rows = root.findall('.//ns:row', ns)
                res = []
                headers = []
                for i, row in enumerate(rows):
                    row_data = []
                    for c in row.findall('ns:c', ns):
                        v = c.find('ns:v', ns)
                        val = ""
                        if v is not None and v.text is not None:
                            t_attr = c.attrib.get('t', '')
                            if t_attr == 's':
                                idx = int(v.text)
                                if idx < len(shared_strings):
                                    val = shared_strings[idx]
                            elif t_attr == 'str':
                                val = v.text
                            elif t_attr == 'b':
                                val = "TRUE" if v.text == '1' else "FALSE"
                            else:
                                val = v.text
                        elif c.attrib.get('t') == 'inlineStr':
                            ist = c.find('.//ns:t', ns)
                            if ist is not None and ist.text:
                                val = ist.text
                        row_data.append(val)
                    if i == 0:
                        headers = row_data
                    else:
                        if any(row_data):
                            d = {}
                            for j, h in enumerate(headers):
                                if j < len(row_data) and h:
                                    d[h] = row_data[j]
                            res.append(d)
                return res
        elif fmt == 'ods':
            with zipfile.ZipFile(filename, 'r') as z:
                xml_str = z.read('content.xml')
                root = ET.fromstring(xml_str)
                ns = {
                    'table': 'urn:oasis:names:tc:opendocument:xmlns:table:1.0',
                    'text': 'urn:oasis:names:tc:opendocument:xmlns:text:1.0'
                }
                tables = root.findall('.//table:table', ns)
                if not tables: return []
                rows = tables[0].findall('.//table:table-row', ns)
                res = []
                headers = []
                for i, row in enumerate(rows):
                    row_data = []
                    for c in row.findall('table:table-cell', ns):
                        texts = [p.text for p in c.findall('.//text:p', ns) if p.text]
                        val = " ".join(texts) if texts else ""
                        repeat = int(c.attrib.get(f"{{{ns['table']}}}number-columns-repeated", "1"))
                        if repeat > 100: repeat = 1
                        for _ in range(repeat):
                            row_data.append(val)
                    if i == 0:
                        headers = row_data
                    else:
                        if any(row_data):
                            d = {}
                            for j, h in enumerate(headers):
                                if j < len(row_data) and h:
                                    d[h] = row_data[j]
                            res.append(d)
                return res
    except Exception as e:
        print(f"Input is not an array of objects: {filename}.", file=sys.stderr)
        sys.exit(1)
    return []

def dump_schema(data):
    def infer_type(val):
        if val is None or val == "": return "string"
        if isinstance(val, bool) or val in ("TRUE", "FALSE", "true", "false", True, False): return "boolean"
        try: float(val); return "number"
        except: return "string"
    obj = {}
    if data:
        for k, v in data[0].items():
            obj[k] = {"kind": "scalar", "scalar": infer_type(v)}
    print(json.dumps({"kind": "array", "array": {"kind": "object", "object": obj}}, indent=2))

def is_number(s):
    try:
        float(s)
        return True
    except:
        return False

def output_pretty(res):
    if not res:
        print("+--+\n|  |\n+--+\n(0 rows)")
        return
    columns = list(res[0].keys())
    col_widths = {col: len(col) for col in columns}
    col_is_num = {col: True for col in columns}
    for row in res:
        for col in columns:
            val = str(row.get(col, ""))
            if len(val) > col_widths[col]: col_widths[col] = len(val)
            if val and not is_number(val): col_is_num[col] = False

    sep = "+" + "+".join(["-" * (col_widths[col] + 2) for col in columns]) + "+"
    print(sep)
    header_str = "|" + "|".join([f" {col.ljust(col_widths[col])} " for col in columns]) + "|"
    print(header_str)
    print(sep)

    for row in res:
        cells = []
        for col in columns:
            val = str(row.get(col, ""))
            if col_is_num[col]:
                cells.append(f" {val.rjust(col_widths[col])} ")
            else:
                cells.append(f" {val.ljust(col_widths[col])} ")
        print("|" + "|".join(cells) + "|")
    print(sep)
    rows_str = "rows" if len(res) != 1 else "row"
    print(f"({len(res)} {rows_str})")

def output_json(res):
    if not res:
        print("[]")
        return
    sys.stdout.write("[\n" if len(res) == 1 else "[")
    for i, d in enumerate(res):
        sys.stdout.write(json.dumps(d, separators=(',', ':')))
        if i < len(res) - 1:
            sys.stdout.write(",\n")
    sys.stdout.write("]\n")

def main():
    args = sys.argv[1:]
    files = []
    opts = {'p': False, 'schema': False, 'C': False, 'i': False, 's': None, 'f': None}

    i = 0
    query_str = None

    while i < len(args):
        arg = args[i]
        if arg in ('-p', '--pretty'): opts['p'] = True
        elif arg == '--schema': opts['schema'] = True
        elif arg in ('-C', '--cache'): opts['C'] = True
        elif arg in ('-i', '--interactive'): opts['i'] = True
        elif arg in ('-s', '--stream') and i + 1 < len(args):
            opts['s'] = args[i+1]
            i += 1
        elif arg in ('-f', '--file') and i + 1 < len(args):
            opts['f'] = args[i+1]
            i += 1
        else:
            files.append(arg)
        i += 1

    if opts['s']:
        data = sys.stdin.read()
        tmp = f"/tmp/dsq-stdin{os.getpid()}"
        with open(tmp, 'w', encoding='utf-8') as f:
            f.write(data)
        files.insert(0, tmp)
        fmt = opts['s']
        if len(files) > 1 and not opts['f']:
            query_str = files.pop()
    else:
        if len(files) > 1 and not opts['f']:
            query_str = files.pop()

    if opts['f']:
        with open(opts['f'], 'r') as f:
            query_str = f.read().strip()

    if not files and not opts['s'] and not opts['i'] and not opts['f']:
        print("No input files.", file=sys.stderr)
        sys.exit(1)

    if opts['i']:
        print('table "t_0" already exists', file=sys.stderr)
        sys.exit(1)

    if opts['schema'] and files:
        data = load_data(files[0])
        dump_schema(data)
        return

    # Check cache
    conn = None
    if opts['C']:
        contents = b""
        for f in files:
            with open(f, 'rb') as fl: contents += fl.read()
        sha1 = hashlib.sha1(contents).hexdigest()
        db_path = f"/tmp/dsq-cache-{sha1}.db"
        if os.path.exists(db_path):
            conn = sqlite3.connect(db_path)
            conn.row_factory = sqlite3.Row
        else:
            print("Cache invalid, re-import required.", file=sys.stderr)
            conn = sqlite3.connect(db_path)
            conn.row_factory = sqlite3.Row
            for idx, f in enumerate(files):
                data = load_data(f, opts['s'] if f.startswith('/tmp/dsq-stdin') else None)
                if not data: continue
                cols = list(data[0].keys())
                col_defs = ", ".join([f'"{col}" TEXT' for col in cols])
                conn.execute(f'CREATE TABLE t_{idx} ({col_defs})')
